{
  if (NR == 1) {
    nkeep = 0;
    for (j = 1; j <= NF; j++) {
      if ($j in seu_to_des) {
        nkeep++;
        keep_seu[nkeep] = $j;
        keep_pos[nkeep] = j + 1;
        keep_des[nkeep] = seu_to_des[$j];
      }
    }
    printf "gene";
    for (k = 1; k <= nkeep; k++) printf "%s%s", OFS, keep_des[k];
    printf "\n";
    next;
  }
  nrows++;
  data[nrows] = $0;
}
END {
  N = nkeep;
  for (k = 1; k <= N; k++) tot[k] = 0;
  for (i = 1; i <= nrows; i++) {
    split(data[i], a, FS);
    for (k = 1; k <= N; k++) tot[k] += a[keep_pos[k]] + 0;
  }
  for (k = 1; k <= N; k++) sorted[k] = tot[k];
  for (i = 2; i <= N; i++) {
    x = sorted[i]; j = i - 1;
    while (j >= 1 && sorted[j] > x) { sorted[j + 1] = sorted[j]; j--; }
    sorted[j + 1] = x;
  }
  if (N % 2 == 1) M = sorted[(N + 1) / 2]; else M = (sorted[N / 2] + sorted[N / 2 + 1]) / 2;
  S = ceil(10 + 0.7 * (N - 10));
  cpm_cut = (10 / M) * 1000000;
  for (i = 1; i <= nrows; i++) {
    split(data[i], a, FS);
    sum = 0; cnt = 0;
    for (k = 1; k <= N; k++) {
      val = a[keep_pos[k]] + 0; sum += val;
      if ((val / tot[k]) * 1000000 >= cpm_cut) cnt++;
    }
    if (cnt >= S && sum >= 1000) {
      printf "%s", a[1];
      for (k = 1; k <= N; k++) printf "%s%s", OFS, a[keep_pos[k]];
      printf "\n";
    }
  }
}
function ceil(x) { return (x == int(x)) ? x : int(x) + 1; }"
